/* Exercise the imported codecs against independently generated bytes. */
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <formats/rchd.h>
#include <encodings/rzstd.h>

/* features_cpu also exports an unused Windows deadline helper. No codec
 * may reach that host wait; satisfy the link and fail if it does. */
#ifdef _WIN32
void retro_sleep_us(unsigned usec) { (void)usec; abort(); }
#endif

static unsigned char *load(const char *dir, const char *name, size_t *size)
{
    char path[4096]; FILE *f; long n; unsigned char *p;
    assert(snprintf(path, sizeof(path), "%s/%s", dir, name) < (int)sizeof(path));
    f = fopen(path, "rb"); assert(f);
    assert(!fseek(f, 0, SEEK_END)); n = ftell(f); assert(n >= 0);
    rewind(f); p = malloc((size_t)n + 1); assert(p);
    assert(fread(p, 1, (size_t)n, f) == (size_t)n); fclose(f);
    *size = (size_t)n; return p;
}

static void image(const char *dir, const char *name, int borrow)
{
    size_t size, raw_size; unsigned char *data = load(dir, name, &size);
    unsigned char *raw = load(dir, "raw.bin", &raw_size);
    unsigned char out[20003]; rchd_request_t req; rchd_t *c = rchd_new();
    int e; unsigned steps = 0, supplied = 0; uint32_t rng = 713;
    assert(c);
    while ((e = rchd_open_step(c, &req)) == RCHD_PENDING) {
        size_t n = req.length > 7 ? 7 : req.length;
        assert(++steps < 100000 && n && req.source == RCHD_SOURCE_SELF);
        assert(req.offset <= size && n <= size - req.offset);
        assert(rchd_feed(c, data + req.offset, n) == RCHD_OK);
    }
    assert(e == RCHD_OK && rchd_info(c)->logical_bytes == raw_size);
    assert(rchd_set_pipeline_depth(c, 1) == RCHD_OK);
    assert(rchd_set_pipeline_depth(c, 2) == RCHD_ERROR_UNSUPPORTED);
    for (unsigned i = 0; i < 2000; i++) {
        rng = rng * 1664525u + 1013904223u;
        size_t off = rng % raw_size;
        rng = rng * 1664525u + 1013904223u;
        size_t n = 1 + rng % (sizeof(out) - 2);
        if (n > raw_size - off) n = raw_size - off;
        memset(out, 0xa5, sizeof(out));
        assert(rchd_read_begin(c, off, out + 1, n) == RCHD_OK);
        steps = 0;
        while ((e = rchd_read_step(c, &req)) == RCHD_PENDING) {
            assert(++steps < 100000);
            if (!req.length) continue; /* hunk completed; next step is bounded */
            assert(req.source == RCHD_SOURCE_SELF && req.offset <= size);
            assert(req.length <= size - req.offset);
            size_t feed = req.length;
            if (borrow) {
                assert(rchd_feed_borrow(c, req.offset, req.source,
                                      data + req.offset, feed) == RCHD_OK);
            } else {
                if (feed > 7) feed = 7;
                assert(rchd_feed_at(c, req.offset, req.source,
                                   data + req.offset, feed) == RCHD_OK);
            }
            supplied++;
        }
        assert(e == RCHD_OK && !memcmp(out + 1, raw + off, n));
        assert(out[0] == 0xa5 && out[n + 1] == 0xa5);
    }
    assert(supplied);
    assert(rchd_read_begin(c, raw_size + 1, out, 1) < 0);
    rchd_free(c); free(data); free(raw);
}

static void zstandard(const char *dir)
{
    rzstd_decoder_t *d = rzstd_decoder_new(); assert(d);
    for (unsigned i = 0; i < 12; i++) {
        char name[64]; size_t n, clen, wrote;
        snprintf(name, sizeof(name), "z%u.raw", i);
        unsigned char *raw = load(dir, name, &n);
        snprintf(name, sizeof(name), "z%u.zst", i);
        unsigned char *compressed = load(dir, name, &clen);
        unsigned char *out = malloc(n + 2); assert(out);
        for (unsigned j = 0; j < 4; j++) {
            memset(out, 0xa5, n + 2);
            assert(rzstd_decode_reuse(d, out + 1, n, compressed, clen,
                                     &wrote) == RZSTD_PROCESS_END);
            assert(wrote == n && !memcmp(out + 1, raw, n));
            assert(out[0] == 0xa5 && out[n + 1] == 0xa5);
            assert(rzstd_decode_reuse(d, out + 1, n, compressed, clen - 1,
                                     &wrote) == RZSTD_PROCESS_ERROR);
        }
        compressed[clen - 1] ^= 1; /* reference encoder includes checksum */
        assert(rzstd_decode_reuse(d, out + 1, n, compressed, clen,
                                 &wrote) == RZSTD_PROCESS_ERROR);
        free(out); free(compressed); free(raw);
    }
    rzstd_decoder_free(d);
}
int main(int argc, char **argv)
{
    assert(argc == 2);
    image(argv[1], "v3.chd", 0); image(argv[1], "v3.chd", 1);
    image(argv[1], "v5.chd", 0); image(argv[1], "v5.chd", 1);
    image(argv[1], "v5-zstd.chd", 0); image(argv[1], "v5-zstd.chd", 1);
    image(argv[1], "v5-lzma.chd", 0); image(argv[1], "v5-lzma.chd", 1);
    zstandard(argv[1]);
    puts("CHD codecs: 16000 byte-oracle reads, short/borrowed feeds, reference Zstandard and error recovery passed");
    return 0;
}
